using GamePush;namespace SaveLoadSystemNamespace {	public class GamePushStrategy : ISaveLoadStrategy {		public void Save(ISaveLoadObject saveObject) {			var jsonData = saveObject.GetSaveLoadData();			GP_Storage.Set(saveObject.objectKey, jsonData);		}				public void Load(ISaveLoadObject saveObject) {			var values = GP_Storage.Get(saveObject.objectKey);			saveObject.RestoreValues(values);		}	}}